def esc(s): return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

W1, W2 = 2300, 7550
RP = '<w:sz w:val="20"/><w:szCs w:val="20"/>'
def p(text, bold=False, center=False, size=20, after=40, indent=0, before=0, left=False):
    jc = '<w:jc w:val="center"/>' if center else ('<w:jc w:val="left"/>' if left else '<w:jc w:val="both"/>')
    rpr = ("<w:b/>" if bold else "") + '<w:sz w:val="%d"/><w:szCs w:val="%d"/>' % (size, size)
    ind = '<w:ind w:left="%d" w:hanging="%d"/>' % (indent, indent) if indent else ""
    return ('<w:p><w:pPr><w:spacing w:before="%d" w:after="%d" w:line="240" w:lineRule="auto"/>%s%s<w:rPr>%s</w:rPr></w:pPr>'
            '<w:r><w:rPr>%s</w:rPr><w:t xml:space="preserve">%s</w:t></w:r></w:p>') % (before, after, ind, jc, rpr, rpr, esc(text))
def cell(paras, w, fill=None, bold=False, center=False, plain=False):
    shd = '<w:shd w:val="clear" w:color="auto" w:fill="%s"/>' % fill if fill else ""
    if isinstance(paras, str): paras = [paras]
    body = "".join(p(t, bold=bold, center=center, left=True) if (bold or center or plain) else p("- " + t, indent=227) for t in paras)
    return '<w:tc><w:tcPr><w:tcW w:w="%d" w:type="dxa"/>%s</w:tcPr>%s</w:tc>' % (w, shd, body)
def row(cells, header=False):
    return '<w:tr><w:trPr>%s</w:trPr>%s</w:tr>' % ("<w:tblHeader/>" if header else "", "".join(cells))
def table(widths, rows):
    return ('<w:tbl><w:tblPr><w:tblW w:w="%d" w:type="dxa"/><w:tblBorders>' % sum(widths) +
            "".join('<w:%s w:val="single" w:sz="4" w:space="0" w:color="auto"/>' % s for s in ("top", "left", "bottom", "right", "insideH", "insideV")) +
            '</w:tblBorders><w:tblLayout w:type="fixed"/><w:tblCellMar><w:left w:w="80" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>' +
            "".join('<w:gridCol w:w="%d"/>' % w for w in widths) + "</w:tblGrid>" + "".join(rows) + "</w:tbl>")
def block(title, items):
    rows = [row([cell("Вид работ", W1, fill="D9D9D9", bold=True, center=True), cell("Что сделано", W2, fill="D9D9D9", bold=True, center=True)], header=True)]
    for kind, lst in items:
        rows.append(row([cell(kind, W1, bold=True), cell(lst, W2)]))
    return p(title, bold=True, size=24, after=80, before=200) + table([W1, W2], rows)

